158:export async function fulfilCheckoutSession(sessionId: string, base = ""): Promise<FulfilResult> {

1	// Single fulfilment path for a paid Stripe Checkout session, shared by BOTH the
2	// success-redirect route and the webhook. Plain server module (not "use server").
3	//
4	// WHY THIS EXISTS (2026-07-25)
5	// Fulfilment used to live in `app/api/stripe/confirm/route.ts` and was gated on
6	// whether `creditCheckoutSession()` returned true. That boolean is true only for
7	// the caller that won the race to insert the wallet credit — and the webhook
8	// calls the same function and discards the result. So:
9	//
10	//   * Race: the webhook's insert lands first, the confirm request gets P2002,
11	//     `credited === false`, and the redirect quietly lands on an empty page.
12	//     $249 charged, $249 credited, no server, no error, no notification.
13	//   * Deterministic: the customer closes the tab before `success_url` resolves,
14	//     so the confirm route never runs at all. Same outcome, 100% reproducible.
15	//
16	// Stripe's own guidance is explicit that a browser redirect must not be the
17	// fulfilment trigger. Now BOTH callers run this, and a `FulfilledSession` row —
18	// its own marker, not a side effect of crediting — decides the single winner.
19	
20	import { db } from "./db";
21	import { classifyCheckoutSession, creditCheckoutSession, retrieveCheckoutSession } from "./stripe";
22	import { saveCardFromPaymentSession } from "./stripe-cards";
23	import { placeOrder } from "./order";
24	import { placeGameOrder } from "./game-order";
25	import { placeHostingCardOrder } from "./actions-hosting";
26	import { placeEmailCardOrder } from "./actions-email-hosting";
27	import { applyResize } from "./resize";
28	import { applyDiskExpand } from "./disk-expand";
29	import { recordDeployFunnelError } from "./deploy-funnel";
30	import { sendMetaConversion } from "./tracking";
31	import { cookies, headers } from "next/headers";
32	
33	export type FulfilResult = {
34	  /** Where the browser should end up. The webhook ignores this. */
35	  redirect: string;
36	  /** True when THIS call performed the fulfilment work. */
37	  fulfilled: boolean;
38	  kind: "order" | "gameOrder" | "hostOrder" | "emailOrder" | "resize" | "diskExpand" | "topup" | "none";
39	  error?: string;
40	};
41	
42	/**
43	 * Claim exclusive responsibility for fulfilling `sessionId`.
44	 * Returns false when another caller already holds the claim — the UNIQUE index,
45	 * not a read-then-write check, is what makes this safe under concurrency.
46	 */
47	async function claim(sessionId: string, kind: string): Promise<boolean> {
48	  try {
49	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionId, kind } });
50	    return true;
51	  } catch (e) {
52	    if ((e as { code?: string })?.code === "P2002") return false; // someone else has it
53	    throw e;
54	  }
55	}
56	
57	async function settle(sessionId: string, status: "DONE" | "FAILED", detail?: string) {
58	  await db.fulfilledSession
59	    .update({ where: { stripeSessionId: sessionId }, data: { status, detail: detail?.slice(0, 500) } })
60	    .catch(() => {});
61	}
62	
63	/**
64	 * Tell the customer their money is safe and someone knows. Called only on a path
65	 * where the card HAS cleared and fulfilment did not happen, so silence is the one
66	 * outcome that is never acceptable.
67	 */
68	async function notifyStalled(userId: string) {
69	  await db.notification
70	    .create({
71	      data: {
72	        userId,
73	        title: "Payment received — we couldn't finish setting up your server",
74	        body: "Your payment is safe and sitting in your wallet. Our team has been alerted; deploy again or contact support and we'll sort it out.",
75	        href: "/dashboard/billing",
76	      },
77	    })
78	    .catch(() => {});
79	}
80	
81	/**
82	 * Report a completed order as an ad-conversion, exactly once, on the WINNING fulfil
83	 * call (this only runs where `fulfilled === true`, so no double count under the
84	 * redirect/webhook race). Fires the server-side Meta Conversions API event — best
85	 * effort, inert unless the pixel id + CAPI token are set, and it never throws into
86	 * fulfilment — then returns the redirect tagged with the SAME event_id and the real
87	 * charged amount (`session.amount_total`, what Stripe actually took), so the browser
88	 * pixel (`PurchaseTracker`) can fire and Meta dedupes the pair into ONE conversion.
89	 * READ-ONLY on money: it reports the amount, it never changes a charge.
90	 */
91	async function reportPurchase(
92	  redirect: string,
93	  session: Awaited<ReturnType<typeof retrieveCheckoutSession>>,
94	  email?: string,
95	  userId?: string,
96	  /** Product kind for the per-funnel Google Ads conversion ("vps" | "game"). */
97	  prod?: string,
98	): Promise<string> {
99	  const value = typeof session.amount_total === "number" ? session.amount_total / 100 : 0;
100	  if (!(value > 0)) return redirect; // free / zero-charge order — nothing to report
101	  const currency = (session.currency ?? "usd").toUpperCase();
102	  // Best-effort match signals from the request: the Meta _fbc/_fbp cookies + UA/IP.
103	  // Wrapped so the webhook path (no browser request scope) simply sends without them.
104	  let fbc: string | undefined, fbp: string | undefined, userAgent: string | undefined, clientIp: string | undefined;
105	  try {
106	    const [ck, h] = await Promise.all([cookies(), headers()]);
107	    fbc = ck.get("_fbc")?.value || undefined;
108	    fbp = ck.get("_fbp")?.value || undefined;
109	    userAgent = h.get("user-agent") ?? undefined;
110	    clientIp = (h.get("x-forwarded-for")?.split(",")[0] ?? "").trim() || undefined;
111	  } catch {
112	    /* no request scope (webhook) — send without cookie/UA signals */
113	  }
114	  const { eventId } = await sendMetaConversion({
115	    eventName: "Purchase",
116	    email,
117	    value,
118	    currency,
119	    sourceUrl: redirect,
120	    fbc,
121	    fbp,
122	    userAgent,
123	    clientIp,
124	    externalId: userId,
125	  });
126	  // SERVER-SIDE Google Ads offline conversion for the paid order, using the captured
127	  // gclid — reliable where the browser gtag is not. Best-effort + idempotent (deduped
128	  // on the Stripe session id). Fires the product-specific action (vps/hosting/game/…)
129	  // AND a generic "purchase". Inert until the Ads API creds are configured.
130	  if (userId) {
131	    try {
132	      const { recordAdsConversion } = await import("./google-ads");
133	      const valueCents = Math.round(value * 100);
134	      if (prod) await recordAdsConversion({ kind: prod, userId, dedupeKey: `${prod}:${session.id}`, valueCents, currency });
135	      await recordAdsConversion({ kind: "purchase", userId, dedupeKey: `purchase:${session.id}`, valueCents, currency });
136	    } catch {
137	      /* tracking is best-effort — the order is already fulfilled */
138	    }
139	  }
140	  const params = new URLSearchParams({ purchase: "1", pv: value.toFixed(2), pc: currency, pe: eventId, ...(prod ? { prod } : {}) });
141	  return `${redirect}${redirect.includes("?") ? "&" : "?"}${params.toString()}`;
142	}
143	
144	/**
145	 * Credit the wallet and fulfil whatever the session was for, exactly once.
146	 * Safe to call repeatedly and concurrently from the redirect and the webhook.
147	 *
148	 * THROWS when Stripe cannot be read. That is deliberate and it is the fix for the
149	 * defect found on 2026-07-27: this function used to ask three helpers for the
150	 * session, each of which swallowed every error into `null`, so a transient Stripe
151	 * failure was indistinguishable from "no purchase metadata" and fell through to
152	 * the top-up branch below reporting `fulfilled: true`. A real order then had its
153	 * card charged with no server, no FulfilledSession row and no notification — and
154	 * because the webhook returns 200 either way, Stripe never retried it. A throw
155	 * lands the browser on `?pending=1` (see app/api/stripe/confirm) and puts the
156	 * failure in the webhook's log, which is loud; declaring it a top-up was silent.
157	 */
158	export async function fulfilCheckoutSession(sessionId: string, base = ""): Promise<FulfilResult> {
159	  // ONE retrieve, one view of the session, shared by the credit and the routing.
160	  const session = await retrieveCheckoutSession(sessionId);
161	  const purpose = classifyCheckoutSession(session);
162	
163	  // Nothing was paid (an abandoned session id, or one replayed before capture).
164	  // Never claim fulfilment for money that has not arrived.
165	  if (purpose.kind === "unpaid") {
166	    return { redirect: `${base}/dashboard/billing`, fulfilled: false, kind: "none" };
167	  }
168	
169	  // Crediting is separately idempotent (UNIQUE stripeSessionId on the wallet
170	  // transaction). We deliberately IGNORE its return value now — it reports who
171	  // won the credit race, which is not the same question as "has this been
172	  // fulfilled", and conflating the two was the bug. A THROW, however, is not a
173	  // race: the money has not reached the wallet, so nothing below may spend it.
174	  await creditCheckoutSession(session);
175	
176	  // Purchase metadata is present but cannot be trusted. Retrying will never fix
177	  // it, so claim the session and record the failure exactly like a failed order:
178	  // reconcilable, and the customer is told. What it must NEVER become is a silent
179	  // wallet top-up, which is precisely what the old `null` fall-through produced.
180	  if (purpose.kind === "unreadable") {
181	    if (await claim(sessionId, "unreadable")) {
182	      await settle(sessionId, "FAILED", purpose.detail);
183	      if (purpose.userId) await notifyStalled(purpose.userId);
184	    }
185	    return {
186	      redirect: `${base}/dashboard/billing?paid=1`,
187	      fulfilled: false,
188	      kind: "none",
189	      error: purpose.detail,
190	    };
191	  }
192	
193	  const order = purpose.kind === "order" ? purpose : null;
194	  if (order) {
195	    if (!(await claim(sessionId, "order"))) {
196	      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "order" };
197	    }
198	    try {
199	      const user = await db.user.findUnique({ where: { id: order.userId } });
200	      if (!user) throw new Error("user not found for paid order");
201	      // Settle the price stamped on the session BEFORE the card was charged — never
202	      // a fresh quote taken now. The customer has already paid the card leg of that
203	      // exact total; re-pricing here and taking the difference out of the wallet is
204	      // the H2 incident (see OrderPrice in lib/order.ts). This is the same shape as
205	      // the resize and disk-expand branches below, which have always passed the
206	      // amount through metadata for this reason.
207	      // No request-scoped IP on the fulfil path (this can run in the webhook), so the
208	      // per-IP cap can't be enforced here — the per-account unique still holds, and
209	      // the first-month-free HOLD was already reserved (per-account AND per-IP) before
210	      // the card was charged, so the double-claim race is closed regardless. Fulfilment
211	      // CONFIRMS that hold via `promoReservationToken` rather than contending for a
212	      // fresh claim. `campaign` rides in via metadata so attribution survives the card
213	      // round-trip even in the webhook (no cookies).
214	      const serverId = await placeOrder(user, order.intent, order.sold, {
215	        ipHash: null,
216	        campaign: order.campaign,
217	        promoReservationToken: order.promoReservationToken,
218	        // Same discipline as the promo hold: the coupon was RESERVED (per-person + global
219	        // cap) before the card was charged, and placeOrder CONFIRMS that hold via this
220	        // token rather than contending for a fresh claim — no double-claim, no over-charge.
221	        couponReservationToken: order.couponReservationToken,
222	      });
223	      await settle(sessionId, "DONE", serverId);
224	      // Record the card this order was paid with (the session set
225	      // setup_future_usage) so the renewal sweep can auto-charge it next cycle.
226	      // Guarded: the money moved and the server exists — card recording must never
227	      // turn a completed fulfilment into a failure.
228	      try {
229	        await saveCardFromPaymentSession(session, order.userId);
230	      } catch {
231	        /* best-effort: fulfilment already succeeded */
232	      }
233	      const redirect = await reportPurchase(`${base}/dashboard/servers/${serverId}`, session, user.email, user.id, "vps");
234	      return { redirect, fulfilled: true, kind: "order" };
235	    } catch (e) {
236	      // Payment is captured and the funds are in the wallet — record the failure
237	      // so it is reconcilable rather than invisible, and tell the customer.
238	      const msg = String((e as Error)?.message ?? e);
239	      await settle(sessionId, "FAILED", msg);
240	      await notifyStalled(order.userId);
241	      // Deploy-funnel: the card CLEARED but the order couldn't be placed — the one
242	      // payment-tail failure only visible server-side (the browser has left the
243	      // wizard, or this is the webhook). Recording it on the Payment step lets the
244	      // admin funnel tell "paid, then failed" from a plain abandon. Best-effort +
245	      // guarded so it never re-enters the money path we're unwinding.
246	      try {
247	        await recordDeployFunnelError({ product: "vps", step: "Payment", stepIndex: 7, errorCode: "PAID_ORDER_FAILED", errorMessage: msg, userId: order.userId });
248	      } catch {
249	        /* analytics must never disturb fulfilment */
250	      }
251	      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "order", error: msg };
252	    }
253	  }
254	
255	  // Game-server order — the game analogue of the `order` branch above. Same claim /
256	  // settle / notify discipline; the card leg was credited to the wallet by
257	  // `creditCheckoutSession` above, then `placeGameOrder` debits the SOLD total back
258	  // out — never a fresh quote taken now (the H2 re-pricing incident). Game carries
259	  // no promo/coupon hold, so there is nothing to confirm and no per-IP concern here.
260	  const gameOrder = purpose.kind === "gameOrder" ? purpose : null;
261	  if (gameOrder) {
262	    if (!(await claim(sessionId, "gameOrder"))) {
263	      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "gameOrder" };
264	    }
265	    try {
266	      const user = await db.user.findUnique({ where: { id: gameOrder.userId } });
267	      if (!user) throw new Error("user not found for paid game order");
268	      const serverId = await placeGameOrder(user, gameOrder.intent, gameOrder.sold);
269	      await settle(sessionId, "DONE", serverId);
270	      // Save the card for off-session renewals (same guard as the order branch).
271	      try {
272	        await saveCardFromPaymentSession(session, gameOrder.userId);
273	      } catch {
274	        /* best-effort: fulfilment already succeeded */
275	      }
276	      const redirect = await reportPurchase(`${base}/dashboard/servers/${serverId}`, session, user.email, user.id, "game");
277	      return { redirect, fulfilled: true, kind: "gameOrder" };
278	    } catch (e) {
279	      // Payment is captured and the funds are in the wallet — record the failure so
280	      // it is reconcilable rather than invisible, and tell the customer.
281	      const msg = String((e as Error)?.message ?? e);
282	      await settle(sessionId, "FAILED", msg);
283	      await notifyStalled(gameOrder.userId);
284	      // Deploy-funnel: card cleared but the game order couldn't be placed — the same
285	      // server-only payment-tail failure as the VPS branch above. Best-effort + guarded.
286	      try {
287	        await recordDeployFunnelError({ product: "game", step: "Payment", stepIndex: 4, errorCode: "PAID_ORDER_FAILED", errorMessage: msg, userId: gameOrder.userId });
288	      } catch {
289	        /* analytics must never disturb fulfilment */
290	      }
291	      return { redirect: `${base}/dashboard/games?paid=1`, fulfilled: false, kind: "gameOrder", error: msg };
292	    }
293	  }
294	
295	  // Shared-hosting order funded by card — the hosting analogue of the `order` branch.
296	  // The card leg was credited to the wallet by `creditCheckoutSession` above; then
297	  // `placeHostingCardOrder` re-verifies this same session server-side and runs the
298	  // audited wallet placement (`placeHostingOrderCore`), which DEBITS the wallet and
299	  // claims its own `hostorder:<key>` marker — so a webhook + redirect can't place two
300	  // accounts even before the FulfilledSession claim below. Same claim/settle/notify
301	  // discipline; card save is best-effort so it can never fail a completed order.
302	  const hostOrder = purpose.kind === "hostOrder" ? purpose : null;
303	  if (hostOrder) {
304	    if (!(await claim(sessionId, "hostOrder"))) {
305	      return { redirect: `${base}/dashboard/hosting`, fulfilled: false, kind: "hostOrder" };
306	    }
307	    try {
308	      const res = await placeHostingCardOrder(sessionId);
309	      if ("skip" in res) throw new Error("session did not classify as a hosting order");
310	      if (!("accountId" in res) || !res.accountId) {
311	        throw new Error(("error" in res && res.error) || "hosting order failed");
312	      }
313	      await settle(sessionId, "DONE", res.accountId);
314	      try {
315	        await saveCardFromPaymentSession(session, hostOrder.userId);
316	      } catch {
317	        /* best-effort: fulfilment already succeeded */
318	      }
319	      return { redirect: `${base}/dashboard/hosting/${res.accountId}`, fulfilled: true, kind: "hostOrder" };
320	    } catch (e) {
321	      const msg = String((e as Error)?.message ?? e);
322	      await settle(sessionId, "FAILED", msg);
323	      await notifyStalled(hostOrder.userId);
324	      try {
325	        await recordDeployFunnelError({ product: "hosting", step: "Payment", stepIndex: 7, errorCode: "PAID_ORDER_FAILED", errorMessage: msg, userId: hostOrder.userId });
326	      } catch {
327	        /* analytics must never disturb fulfilment */
328	      }
329	      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "hostOrder", error: msg };
330	    }
331	  }
332	
333	  // Business-email order funded by card — the email analogue of the branch above. The
334	  // card leg was credited to the wallet; `placeEmailCardOrder` re-verifies the session
335	  // and runs `orderEmailHostingCore`, which DEBITS the wallet and creates the
336	  // subscription (its domain dupe guard is the placement idempotency).
337	  const emailOrder = purpose.kind === "emailOrder" ? purpose : null;
338	  if (emailOrder) {
339	    if (!(await claim(sessionId, "emailOrder"))) {
340	      return { redirect: `${base}/dashboard/email`, fulfilled: false, kind: "emailOrder" };
341	    }
342	    try {
343	      const res = await placeEmailCardOrder(sessionId);
344	      if ("skip" in res) throw new Error("session did not classify as an email order");
345	      if (res.error || !res.ok) throw new Error(res.error || "email order failed");
346	      await settle(sessionId, "DONE");
347	      try {
348	        await saveCardFromPaymentSession(session, emailOrder.userId);
349	      } catch {
350	        /* best-effort: fulfilment already succeeded */
351	      }
352	      return { redirect: `${base}/dashboard/email?paid=1`, fulfilled: true, kind: "emailOrder" };
353	    } catch (e) {
354	      const msg = String((e as Error)?.message ?? e);
355	      await settle(sessionId, "FAILED", msg);
356	      await notifyStalled(emailOrder.userId);
357	      return { redirect: `${base}/dashboard/email?paid=1`, fulfilled: false, kind: "emailOrder", error: msg };
358	    }
359	  }
360	
361	  const resize = purpose.kind === "resize" ? purpose : null;
362	  if (resize) {
363	    const back = `${base}/dashboard/servers/${resize.serverId}`;
364	    if (!(await claim(sessionId, "resize"))) {
365	      return { redirect: back, fulfilled: false, kind: "resize" };
366	    }
367	    try {
368	      await applyResize({
369	        serverId: resize.serverId,
370	        planId: resize.planId,
371	        actorUserId: resize.userId,
372	        chargeCents: resize.chargeCents,
373	      });
374	      await settle(sessionId, "DONE", resize.serverId);
375	      // `createResizeCheckout` now also sets setup_future_usage (this can be a
376	      // customer's first-ever card charge — e.g. an order the wallet or a 100%-off
377	      // promo fully covered), so record it here too. Best-effort: the upgrade
378	      // already succeeded.
379	      try {
380	        await saveCardFromPaymentSession(session, resize.userId);
381	      } catch {
382	        /* best-effort: fulfilment already succeeded */
383	      }
384	      return { redirect: back, fulfilled: true, kind: "resize" };
385	    } catch (e) {
386	      const msg = String((e as Error)?.message ?? e);
387	      await settle(sessionId, "FAILED", msg);
388	      await notifyStalled(resize.userId);
389	      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "resize", error: msg };
390	    }
391	  }
392	
393	  const expand = purpose.kind === "diskExpand" ? purpose : null;
394	  if (expand) {
395	    const back = `${base}/dashboard/servers/${expand.serverId}`;
396	    if (!(await claim(sessionId, "diskExpand"))) {
397	      return { redirect: `${back}?tab=resize`, fulfilled: false, kind: "diskExpand" };
398	    }
399	    try {
400	      await applyDiskExpand({
401	        serverId: expand.serverId,
402	        addGB: expand.addGB,
403	        actorUserId: expand.userId,
404	        chargeCents: expand.chargeCents,
405	      });
406	      await settle(sessionId, "DONE", expand.serverId);
407	      // Same reasoning as the resize branch above: `createDiskExpandCheckout` now
408	      // sets setup_future_usage too, and this can be a customer's first-ever card
409	      // charge. Best-effort: the expansion already succeeded.
410	      try {
411	        await saveCardFromPaymentSession(session, expand.userId);
412	      } catch {
413	        /* best-effort: fulfilment already succeeded */
414	      }
415	      return { redirect: `${back}?tab=resize`, fulfilled: true, kind: "diskExpand" };
416	    } catch (e) {
417	      const msg = String((e as Error)?.message ?? e);
418	      await settle(sessionId, "FAILED", msg);
419	      await notifyStalled(expand.userId);
420	      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "diskExpand", error: msg };
421	    }
422	  }
423	
424	  // Plain wallet top-up: crediting above is the whole job. Reached ONLY when the
425	  // session genuinely carried no purchase metadata — never because we failed to
426	  // read it (that throws) and never because we failed to parse it ("unreadable").
427	  //
428	  // The top-up session also set setup_future_usage, so record the card here too —
429	  // a customer who only ever tops up their wallet still ends up with a chargeable
430	  // card on file for renewals. Best-effort; the credit above already happened.
431	  if (purpose.kind === "topup" && purpose.userId) {
432	    try {
433	      await saveCardFromPaymentSession(session, purpose.userId);
434	    } catch {
435	      /* best-effort: the wallet was already credited */
436	    }
437	  }
438	  return { redirect: `${base}/dashboard/billing?paid=1`, fulfilled: true, kind: "topup" };
439	}
440

1	import { NextRequest, NextResponse } from "next/server";
2	import { stripe, stripeConfigured } from "@/lib/stripe";
3	import { fulfilCheckoutSession } from "@/lib/fulfil-checkout";
4	import { releaseReservation } from "@/lib/promo-redemption";
5	import { releaseOrderCouponReservation } from "@/lib/coupon-redemption";
6	import type Stripe from "stripe";
7	
8	export async function POST(req: NextRequest) {
9	  if (!stripeConfigured() || !process.env.STRIPE_WEBHOOK_SECRET) {
10	    return NextResponse.json({ error: "not configured" }, { status: 400 });
11	  }
12	  const sig = req.headers.get("stripe-signature");
13	  if (!sig) return NextResponse.json({ error: "missing signature" }, { status: 400 });
14	  const raw = await req.text();
15	
16	  let event;
17	  try {
18	    event = stripe().webhooks.constructEvent(raw, sig, process.env.STRIPE_WEBHOOK_SECRET);
19	  } catch {
20	    return NextResponse.json({ error: "invalid signature" }, { status: 400 });
21	  }
22	
23	  if (event.type === "checkout.session.completed") {
24	    const session = event.data.object as { id: string };
25	    // FULFIL, don't just credit. This used to call `creditCheckoutSession` and
26	    // throw the result away, which meant the webhook credited the wallet and then
27	    // — by winning the race — caused the success-redirect to see `credited: false`
28	    // and skip provisioning entirely. The webhook is the reliable signal (the
29	    // redirect may never happen at all), so it must be able to fulfil on its own.
30	    // `fulfilCheckoutSession` is idempotent via UNIQUE(FulfilledSession), so the
31	    // two callers racing is safe: exactly one does the work.
32	    //
33	    // Errors are swallowed deliberately — returning non-2xx makes Stripe retry the
34	    // event, and the failure is already recorded on the FulfilledSession row and
35	    // surfaced to the customer.
36	    try {
37	      await fulfilCheckoutSession(session.id);
38	    } catch (e) {
39	      console.error("[stripe-webhook] fulfil failed", session.id, e);
40	    }
41	  }
42	
43	  // A checkout the customer never completed: Stripe expires it (we cap the payable
44	  // window at ORDER_CHECKOUT_EXPIRES_MS). RELEASE any first-month-free hold it carried
45	  // so the customer's one-time offer is returned promptly rather than waiting for the
46	  // worker sweep. Guarded to RESERVED, so a completed+confirmed grant is never revoked.
47	  // (If this event type isn't enabled in the Stripe dashboard, the worker sweep is the
48	  // backstop — the hold's reservedUntil has passed by the time the session expires.)
49	  if (event.type === "checkout.session.expired") {
50	    const session = event.data.object as Stripe.Checkout.Session;
51	    const token = session.metadata?.nxeonPromoReservation;
52	    if (token) {
53	      try {
54	        await releaseReservation(token);
55	      } catch (e) {
56	        console.error("[stripe-webhook] release reservation failed", token, e);
57	      }
58	    }
59	    // Same for a checkout-coupon hold — return its per-person slot AND its global-cap
60	    // slot (timesRedeemed decrement inside releaseOrderCouponReservation). Guarded to
61	    // RESERVED, so a completed+confirmed CONSUMED redemption is never revoked.
62	    const couponToken = session.metadata?.nxeonCouponReservation;
63	    if (couponToken) {
64	      try {
65	        await releaseOrderCouponReservation(couponToken);
66	      } catch (e) {
67	        console.error("[stripe-webhook] release coupon reservation failed", couponToken, e);
68	      }
69	    }
70	  }
71	
72	  return NextResponse.json({ received: true });
73	}
