136	/** Every function that opens a Checkout session to collect real money from a
137	 *  customer for a NEW purchase/upgrade (as opposed to `createOutstandingCheckout`
138	 *  / `createOutstandingEmbedded`, which settle an existing renewal balance for an
139	 *  account that — by the time it is dunning — already went through one of these). */
140	const MONEY_CHECKOUT_FNS = [
141	  "createOrderCheckout",
142	  "createGameOrderCheckout",
143	  "createHostingOrderCheckout",
144	  "createEmailOrderCheckout",
145	  "createResizeCheckout",
146	  "createDiskExpandCheckout",
147	];
