149	function functionBody(src: string, name: string): string {
150	  const start = src.indexOf(`function ${name}(`);
151	  assert.ok(start >= 0, `could not find function ${name} in lib/stripe.ts`);
152	  // Find the END of the parameter list first (balancing PARENS, not braces) — a
153	  // param can itself carry an object-type annotation like `resize: { … }`, whose
154	  // own `{`/`}` would otherwise be mistaken for the function body's braces.
155	  const parenStart = src.indexOf("(", start);
156	  let pdepth = 0;
157	  let parenEnd = -1;
158	  for (let i = parenStart; i < src.length; i++) {
159	    if (src[i] === "(") pdepth++;
160	    else if (src[i] === ")") {
161	      pdepth--;
162	      if (pdepth === 0) {
163	        parenEnd = i;
164	        break;
165	      }
166	    }
167	  }
168	  assert.ok(parenEnd >= 0, `unbalanced parens reading ${name}'s parameter list`);
169	  // Now the function body's opening `{` is the first one after the param list
170	  // (past any return-type annotation).
171	  const openBrace = src.indexOf("{", parenEnd);
172	  let depth = 0;
173	  for (let i = openBrace; i < src.length; i++) {
174	    if (src[i] === "{") depth++;
175	    else if (src[i] === "}") {
176	      depth--;
177	      if (depth === 0) return src.slice(start, i + 1);
178	    }
179	  }
180	  throw new Error(`unbalanced braces reading ${name}`);
181	}
