3	import { useMemo } from "react";
4	import { loadStripe, type Stripe } from "@stripe/stripe-js";
5	import { EmbeddedCheckoutProvider, EmbeddedCheckout } from "@stripe/react-stripe-js";
6	
7	/**
8	 * The ONE payment surface for the whole platform — Stripe Embedded Checkout rendered
9	 * in a modal ON our own page. Nobody is ever redirected to a Stripe-branded page: the
10	 * payment UI mounts inside this dialog (styled by our appearance settings), and on
11	 * completion Stripe navigates to the session's `return_url` — our own `/api/stripe/confirm`
12	 * route — which runs the SAME idempotent fulfilment the webhook does. So the audited
13	 * fulfilment engine is untouched; only the presentation changed from "redirect" to
14	 * "embedded modal".
15	 *
16	 * Usage: a flow's server action now returns `{ clientSecret, publishableKey }` (from a
17	 * Checkout Session created with `ui_mode: "embedded"`). The caller stores it in state and
18	 * renders `<StripeCheckoutModal ... onClose={...} />`.
19	 */
20	
21	// loadStripe returns a singleton per key — cache so we don't re-init Stripe.js each open.
22	const stripeCache = new Map<string, Promise<Stripe | null>>();
23	function stripeFor(pk: string): Promise<Stripe | null> {
24	  let p = stripeCache.get(pk);
25	  if (!p) {
26	    p = loadStripe(pk);
27	    stripeCache.set(pk, p);
28	  }
29	  return p;
30	}
31	
32	export function StripeCheckoutModal({
33	  clientSecret,
34	  publishableKey,
35	  onClose,
36	  title = "Checkout",
37	}: {
38	  clientSecret: string;
39	  publishableKey: string;
40	  onClose: () => void;
41	  title?: string;
42	}) {
43	  const stripePromise = useMemo(() => stripeFor(publishableKey), [publishableKey]);
44	
45	  return (
46	    <div
47	      className="fixed inset-0 z-[100] flex items-start justify-center overflow-y-auto bg-black/60 p-4 backdrop-blur-sm sm:p-8"
48	      role="dialog"
49	      aria-modal="true"
50	      aria-label={title}
51	    >
52	      <div className="relative my-auto w-full max-w-xl rounded-2xl border border-white/10 bg-navy-950 p-2 shadow-2xl">
53	        <div className="flex items-center justify-between px-3 pb-1 pt-2">
54	          <span className="text-sm font-semibold text-slate-200">{title}</span>
55	          <button
56	            type="button"
57	            onClick={onClose}
58	            aria-label="Close checkout"
59	            className="rounded-lg px-2 py-1 text-slate-400 transition hover:bg-white/5 hover:text-white"
60	          >
61	            ✕
62	          </button>
63	        </div>
64	        {/* Embedded Checkout renders inside this container — no navigation to Stripe. */}
65	        <div className="rounded-xl bg-white p-1">
66	          <EmbeddedCheckoutProvider stripe={stripePromise} options={{ clientSecret }}>
67	            <EmbeddedCheckout />
68	          </EmbeddedCheckoutProvider>
69	        </div>
70	      </div>
71	    </div>
72	  );
73	}
