export type SeoConnectionInfo = {
  configured: boolean;
  connected: boolean;
  accountEmail: string | null;
  siteUrl: string | null;
  connectedAt: string | null;
  lastSyncAt: string | null;
};

export async function getSeoConnectionInfo(): Promise<SeoConnectionInfo> {
  await requireArea("platform");
  const status = await getGscConnectionStatus();
  return {
    configured: gscConfigured(),
    connected: status.connected,
    accountEmail: status.accountEmail,
    siteUrl: status.siteUrl,
    connectedAt: status.connectedAt ? status.connectedAt.toISOString() : null,
    lastSyncAt: status.lastSyncAt ? status.lastSyncAt.toISOString() : null,
  };
}

export async function disconnectSeoConnection(): Promise<{ ok?: boolean; error?: string }> {
  await requireArea("platform");
  await disconnectGsc();
  revalidatePath(SETTINGS_PATH);
  return { ok: true };
}
